setup:
CREATE TABLE towers AS SELECT * FROM (VALUES
  (1, ST_GeomFromText('POLYGON((0 0, 4 0, 4 4, 0 4, 0 0))')),
  (2, ST_GeomFromText('POLYGON((2 0, 6 0, 6 4, 2 4, 2 0))')),
  (3, ST_GeomFromText('POLYGON((20 0, 24 0, 24 4, 20 4, 20 0))'))
) t(tower_id, geom);

solution:
LOAD spatial;

SELECT ST_NumGeometries(ST_Union_Agg(geom)) AS coverage_blobs
FROM towers;
